import type { IncomingMessage } from "http";
import type { Duplex } from "stream";
import { WebSocketServer, createWebSocketStream } from "ws";
import { Aedes } from "aedes";

export interface MqttServiceCallbacks {
  onCommand: (deviceId: string, action: string, raw: string) => void;
  onStatus: (deviceId: string, data: any) => void;
}

export class MqttBrokerService {
  private broker: any;
  private wss: WebSocketServer;
  private callbacks?: MqttServiceCallbacks;

  constructor() {
    this.broker = new (Aedes as any)();
    this.wss = new WebSocketServer({ noServer: true });

    this.wss.on("connection", (ws) => {
      const stream = createWebSocketStream(ws);
      this.broker.handle(stream as Duplex);
    });

    this.broker.on("publish", (packet: any, client: any) => {
      if (!client) return; // ignore internal broker emits
      const topic: string = packet.topic || "";
      const payloadStr: string = packet.payload ? packet.payload.toString().trim() : "";

      // Topic 1: devices/{deviceId}/command
      const cmdMatch = topic.match(/^devices\/([^/]+)\/command$/);
      if (cmdMatch) {
        const deviceId = cmdMatch[1];
        if (this.callbacks?.onCommand) {
          this.callbacks.onCommand(deviceId, payloadStr.toLowerCase(), payloadStr);
        }
        return;
      }

      // Topic 2: devices/{deviceId}/status or devices/{deviceId}/ack
      const statusMatch = topic.match(/^devices\/([^/]+)\/(status|ack)$/);
      if (statusMatch) {
        const deviceId = statusMatch[1];
        try {
          const parsed = JSON.parse(payloadStr);
          if (this.callbacks?.onStatus) {
            this.callbacks.onStatus(deviceId, parsed);
          }
        } catch {
          // not JSON, ignore or log
        }
      }
    });

    this.broker.on("client", (client: any) => {
      console.log(`[MQTT] Client connected: ${client?.id}`);
    });

    this.broker.on("clientDisconnect", (client: any) => {
      console.log(`[MQTT] Client disconnected: ${client?.id}`);
    });
  }

  public setCallbacks(callbacks: MqttServiceCallbacks) {
    this.callbacks = callbacks;
  }

  public handleUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer) {
    const url = request.url || "";
    if (url.startsWith("/mqtt") || url.startsWith("/ws")) {
      this.wss.handleUpgrade(request, socket, head, (ws) => {
        this.wss.emit("connection", ws, request);
      });
      return true;
    }
    return false;
  }

  public publishCommand(deviceId: string, command: string): Promise<void> {
    return new Promise((resolve) => {
      try {
        this.broker.publish(
          {
            cmd: "publish",
            qos: 0,
            dup: false,
            retain: false,
            topic: `devices/${deviceId}/command`,
            payload: Buffer.from(command),
          },
          (err: any) => {
            if (err) console.error("[MQTT] Publish error:", err);
            resolve();
          }
        );
      } catch (err) {
        console.error("[MQTT] Exception in publishCommand:", err);
        resolve();
      }
    });
  }

  public getConnectedClientsCount(): number {
    return this.broker.connectedClients || 0;
  }
}

export const mqttBroker = new MqttBrokerService();
