import fs from "fs";
import path from "path";
import crypto from "crypto";

export interface CustomAudioMeta {
  id: string;
  name: string;
  url: string;
  fileName?: string;
  sizeBytes: number;
  mimeType: string;
  createdAt: number;
  isGoogleDrive?: boolean;
}

const UPLOADS_DIR = path.join(process.cwd(), "uploads", "audio");
const META_FILE = path.join(UPLOADS_DIR, "audio_meta.json");

// Ensure upload directory exists
if (!fs.existsSync(UPLOADS_DIR)) {
  fs.mkdirSync(UPLOADS_DIR, { recursive: true });
}

function loadMeta(): CustomAudioMeta[] {
  try {
    if (fs.existsSync(META_FILE)) {
      const raw = fs.readFileSync(META_FILE, "utf-8");
      return JSON.parse(raw);
    }
  } catch (e) {
    console.warn("Could not read audio meta file:", e);
  }
  return [];
}

function saveMeta(list: CustomAudioMeta[]) {
  try {
    fs.writeFileSync(META_FILE, JSON.stringify(list, null, 2), "utf-8");
  } catch (e) {
    console.warn("Could not save audio meta file:", e);
  }
}

export class AudioService {
  public static getUploadsDir(): string {
    return UPLOADS_DIR;
  }

  public static listAudio(): CustomAudioMeta[] {
    const list = loadMeta();
    // Filter out uploaded files that might have been deleted from disk
    return list.filter((item) => {
      if (item.isGoogleDrive) return true;
      if (item.fileName) {
        return fs.existsSync(path.join(UPLOADS_DIR, item.fileName));
      }
      return true;
    });
  }

  public static getAudioById(id: string): CustomAudioMeta | undefined {
    const list = loadMeta();
    return list.find((item) => item.id === id);
  }

  public static getFilePath(fileName: string): string {
    return path.join(UPLOADS_DIR, fileName);
  }

  public static saveUploadedAudio(
    rawFileName: string,
    base64DataUrl: string,
    mimeType: string = "audio/mpeg"
  ): CustomAudioMeta {
    // Strip data URL prefix if present (e.g. data:audio/mp3;base64,...)
    let base64 = base64DataUrl;
    if (base64DataUrl.includes(",")) {
      const parts = base64DataUrl.split(",");
      base64 = parts[1];
      const match = parts[0].match(/:(.*?);/);
      if (match && match[1]) {
        mimeType = match[1];
      }
    }

    const buffer = Buffer.from(base64, "base64");
    const cleanExt = path.extname(rawFileName).toLowerCase() || ".mp3";
    const safeBaseName = path
      .basename(rawFileName, cleanExt)
      .replace(/[^a-zA-Z0-9_\-\s]/g, "")
      .trim()
      .slice(0, 40) || "custom_audio";
    
    const uniqueId = `audio_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`;
    const fileName = `${safeBaseName}_${uniqueId}${cleanExt}`;
    const filePath = path.join(UPLOADS_DIR, fileName);

    fs.writeFileSync(filePath, buffer);

    const item: CustomAudioMeta = {
      id: uniqueId,
      name: rawFileName || safeBaseName,
      fileName,
      url: `/uploads/audio/${encodeURIComponent(fileName)}`,
      sizeBytes: buffer.length,
      mimeType,
      createdAt: Date.now(),
      isGoogleDrive: false,
    };

    const currentList = loadMeta();
    currentList.unshift(item);
    saveMeta(currentList);

    return item;
  }

  public static addGoogleDriveAudio(rawUrl: string, customName?: string): CustomAudioMeta {
    const cleanUrl = rawUrl.trim();
    // Match Google Drive ID from various URL formats:
    // https://drive.google.com/file/d/FILE_ID/view
    // https://drive.google.com/open?id=FILE_ID
    // https://drive.google.com/uc?id=FILE_ID
    let fileId = "";
    const match1 = cleanUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    const match2 = cleanUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);

    if (match1 && match1[1]) {
      fileId = match1[1];
    } else if (match2 && match2[1]) {
      fileId = match2[1];
    } else {
      fileId = cleanUrl; // fallback if already an ID or direct link
    }

    const directStreamUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;
    const uniqueId = `gdrive_${fileId.slice(0, 10)}_${Date.now()}`;

    const item: CustomAudioMeta = {
      id: uniqueId,
      name: customName?.trim() || `Google Drive Audio (${fileId.slice(0, 8)}...)`,
      url: directStreamUrl,
      sizeBytes: 0,
      mimeType: "audio/mpeg",
      createdAt: Date.now(),
      isGoogleDrive: true,
    };

    const currentList = loadMeta();
    currentList.unshift(item);
    saveMeta(currentList);

    return item;
  }

  public static deleteAudio(id: string): boolean {
    const currentList = loadMeta();
    const target = currentList.find((i) => i.id === id);
    if (!target) return false;

    if (target.fileName) {
      const filePath = path.join(UPLOADS_DIR, target.fileName);
      if (fs.existsSync(filePath)) {
        try {
          fs.unlinkSync(filePath);
        } catch {}
      }
    }

    const updated = currentList.filter((i) => i.id !== id);
    saveMeta(updated);
    return true;
  }
}
